cat > /home/user/setup_local_proxy.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

printf 'Enter deployment tier: '
read -r tier

mkdir -p /home/user/certs

openssl req -x509 -newkey rsa:2048 -nodes \
  -keyout /home/user/certs/key.pem \
  -out /home/user/certs/cert.pem \
  -days 365 \
  -subj '/CN=localhost' > /dev/null 2>&1

cat > /home/user/proxy.conf <<'NGINX'
pid /home/user/nginx.pid;
error_log /home/user/error.log;

events {}

http {
    access_log /home/user/access.log;

    server {
        listen 127.0.0.1:8443 ssl;
        server_name localhost;

        ssl_certificate /home/user/certs/cert.pem;
        ssl_certificate_key /home/user/certs/key.pem;

        location / {
            proxy_pass http://127.0.0.1:8080;
        }
    }
}
NGINX

nginx -t -c /home/user/proxy.conf

fingerprint=$(openssl x509 -in /home/user/certs/cert.pem -noout -fingerprint -sha256 | cut -d'=' -f2)
echo "Tier: ${tier}, Cert SHA256: ${fingerprint}" >> /home/user/deploy.log
EOF
